import * as M from './model.js';
const KEY='flamingo-farmer-billing-mobile-v1',app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let state,storageFailed=false;try{state=JSON.parse(localStorage.getItem(KEY));}catch{}if(!state||state.schema!==1||!Array.isArray(state.bills))state=M.seed();
M.migrate(state);
if(state.saveRequest?.status==='pending')state.saveRequest.status='unknown';
if(state.saveRequest?.status==='unknown')location.hash='save-unknown';
let marketReturn='home',marketMode='billing',historyMarket=state.selected||'all',catalogQuery='',historyQuery='',error='',saveMode='success',receiptMode='success',guidanceMode='available',aiMode='success',aiUrl=null,aiSample=true,aiToken=0,menuLine=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(n,c='')=>`<img class="icon ${c}" src="assets/${n}.svg" alt="">`;
const button=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,route,cls='')=>button(label,'go',cls,`data-route="${route}"`);
const count=(n,noun='item')=>`${n} ${noun}${n===1?'':'s'}`;
const items=()=>state.draft?.items||[];
const qstr=i=>i.unit==='kg'?Number(i.qty).toFixed(2):String(i.qty);
const billById=id=>state.bills.find(b=>b.id===id);
const badge=(text,tone='')=>`<span class="badge ${tone}">${text}</span>`;
const inputError=()=>error?`<div class="form-error" role="alert">${esc(error)}</div>`:'';
const receiptText={ready:'Receipt ready to send',sending:'Sending receipt',sent:'Receipt sent',failed:'Receipt failed',not_requested:'Receipt not requested'};
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageFailed=false;}catch{storageFailed=true;toast('Storage is unavailable. Keep this tab open to retain your demo progress.');}}
function toast(t){const node=document.querySelector('#toast');node.textContent=t;clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.textContent='',3600);}
function route(){return (location.hash.slice(1)||'home').split('/');}
function go(to){if(M.locked(state)&&!['saving','save-unknown'].includes(to.split('/')[0])){toast('Check the existing save result first.');to='save-unknown';}error='';dialog.close();if(location.hash.slice(1)!==to)window.history.pushState(null,'','#'+to);render();}
function marketBlock(mid=state.selected,change=true,stallId=state.selectedStall){const m=M.market(mid);if(!m)return button('All assigned markets','history-market','market-block full');return `<button class="market-block full" data-action="${change?'open-markets':'market-info'}"><span class="icon-well">${icon('catalog-imgMarketStore')}</span><span class="market-info"><b>${esc(m.name)}</b><small>${route()[0]==='history'?'All stalls':'Stall '+esc(stallId||m.stall)}</small></span>${change?icon('catalog-imgMarketDropdownChevron','chevron'):''}</button>`;}
function totalsFooter(label,action,primary=false){return `<footer class="app-footer"><b class="total">${count(items().length)} · ${M.money(M.total(items()))}</b>${button(label,action,`full ${primary?'primary':''}`,!items().length?'disabled':'')}</footer>`;}
function productLines(lines,menus=false){return `<div class="product-lines">${lines.map(i=>`<div class="product-line"><div class="line-info"><b>${esc(i.name)}</b><small>${qstr(i)} ${esc(i.unit)} × ${M.money(i.rate)}/${esc(i.unit)}</small></div><b class="line-amount">${M.money(M.amount(i)/100)}</b>${menus?`<button class="dots" aria-label="Options for ${esc(i.name)}" data-action="item-menu" data-id="${i.id}">···</button>`:''}</div>`).join('')}</div>`;}
function historyRows(bills,showMarket=false){return bills.map(b=>`<button class="history-row" data-action="detail" data-id="${b.id}"><div><div class="identity"><b>${b.id}</b><b>${M.money(M.total(b.items))}</b></div><small>${b.time} · ${count(b.items.length,'product')}${!showMarket?' · Stall '+M.stallFor(b):''}${showMarket?`<br>${M.market(b.marketId).short} · Stall ${M.stallFor(b)}`:''}</small><small class="receipt-label">${receiptText[b.receipt]}</small></div>${icon('home-imgIcon16ChevronDown','chevron right')}</button>`).join('');}
function home(){const m=M.market(state.selected),bills=state.bills.filter(b=>!m||b.marketId===m.id);const draft=state.draft?.items.length;return `${m?marketBlock():''}<h2>Hello, Ramesh</h2><p class="muted">Today's overview · ${m?m.name:'All assigned markets'}</p><section class="panel revenue"><p>Today's revenue</p><strong class="metric">${M.money(M.total(bills.flatMap(b=>b.items)))}</strong><p>${count(bills.length,'saved bill')}</p><small>${m?'Before this bill · '+m.name:'Select a market to start selling'}</small></section><div class="kpis">${[['Bills','home-imgBillsIcon',bills.length],['Customers','home-imgCustomersIcon',bills.length],['Products','home-imgProductsIcon',bills.reduce((v,b)=>v+b.items.length,0)]].map(([n,i,v])=>`<div class="kpi"><div><span class="icon-well">${icon(i)}</span><b>${v}</b></div><small>${n}</small></div>`).join('')}</div>${button(m?(draft?'Resume current bill':'Start new bill'):'Select market',m?'start':'open-markets','primary full')}<div class="section-heading"><h3>Recent bills</h3>${button('View all','history','small-btn')}</div><section class="panel ledger">${historyRows(bills.slice(0,3),true)||'<p class="empty-inline">No saved bills yet.</p>'}</section>`;}
function markets(){return `<section class="panel"><h2>Select your market</h2><p class="muted">${marketMode==='history'?'Choose a market to view saved bills across its stalls.':'Choose an open market. Select your stall next.'}</p>${marketMode==='history'?button('All assigned markets','select-market','full','data-id="all"'):''}${M.MARKETS.map(m=>`<section class="panel market-choice"><b>${m.name}</b><p>Nashik · ${count(m.stalls.length,'assigned stall')}</p><small>${m.closed?'Tomorrow':'Open'} · ${m.hours}</small>${button(m.closed?'Opens tomorrow':(m.id==='vidya'?'Select Vidya Vikas':'Choose '+m.short),'select-market','full',`data-id="${m.id}" ${m.closed?'disabled':''}`)}</section>`).join('')}${link(marketReturn==='home'?'Back to Home':'Go back',marketReturn,'full')}</section>`;}
function catalog(){return `${marketBlock()}<section class="panel flow-card"><h2>${items().length?'Add another product':'Add your first product'}</h2><p class="muted">Build one bill with as many products as you need.</p><label class="search">${icon('catalog-imgIcon')}<input type="search" id="catalog-search" placeholder="Search products" aria-label="Search products" value="${esc(catalogQuery)}"></label><div id="catalog-results">${catalogResults()}</div>${button('Use AI capture','ai-capture','full')}</section>`;}
function catalogResults(){const ps=M.PRODUCTS.filter(p=>p.name.toLowerCase().includes(catalogQuery.toLowerCase()));return ps.map(p=>`<div class="catalog-row"><div><p>${p.name}</p><small>${M.money(p.rate)}/${p.unit} · ${p.unit==='kg'?'Weigh in kg':'Count bunches'}</small></div>${button(items().some(i=>i.productId===p.id)?'Edit':'Select','select-product','',`data-id="${p.id}"`)}</div>`).join('')||'<div class="empty-inline"><b>No products found</b><p>Try a different product name.</p></div>';}
function startEditor(pid,lineId=null,ai=false){const p=M.product(pid),existing=items().find(i=>i.id===lineId);state.editor=existing?{...M.clone(existing),editing:true,guidance:guidanceMode}:{productId:pid,qty:ai?'2.50':'',rate:String(p.rate),source:ai?'ai-reviewed':'manual',editing:false,guidance:guidanceMode,ai};persist();go(ai?'ai-review':'editor');}
function guidance(e,p){if(!p.guidance)return '';const g=p.guidance,stage=e.guidance;if(stage==='loading')return `<section class="guidance"><div class="icon-heading"><span class="spinner"></span><h3>Checking market guidance</h3></div><small>You can still choose your final rate.</small>${button('Check suggestion','load-guidance','full')}</section>`;if(['unavailable','failed'].includes(stage))return `<section class="guidance"><h3>${stage==='failed'?'Couldn’t load guidance':'No market guidance available'}</h3><small>Your final rate stays ${M.money(e.rate)}/${p.unit}.</small>${button('Try again','load-guidance','full')}</section>`;return `<section class="guidance ${stage==='applied'?'applied':''}"><div class="icon-heading">${icon('rate-imgBenchmarkIcon')}<h3>${stage==='applied'?'Suggestion applied':'Market guidance · Sample'}</h3></div>${stage==='stale'?badge('Older market data','amber'):''}<div class="benchmark-values"><div><small>Suggested rate</small><b>₹${g.rate}</b></div><div><small>Market range</small><b>₹${g.min}–₹${g.max}</b></div></div><small>Per ${p.unit} · Sample data<br>Vidya Vikas · 10:20 AM</small>${button(`${stage==='applied'?'Applied':'Apply suggestion'} · ₹${g.rate}/${p.unit}`,'apply-guidance','full',stage==='applied'?'disabled':'')}${stage==='late'?'<small>Your edited rate is preserved. Apply only if you want to replace it.</small>':''}</section>`;}
function editor(ai=false){const e=state.editor;if(!e)return `<section class="panel"><h2>Choose a product to continue</h2>${link('Browse products','catalog','primary full')}</section>`;const p=M.product(e.productId);return `${marketBlock()}<form id="editor-form" class="panel flow-card">${p.guidance?'':`<h2>${e.editing?'Edit product':'Add a product'}</h2><small>${ai?'Suggested Tomato and 2.50 kg. Review both before adding.':'Check quantity and your final rate, then '+(e.editing?'save.':'add.')}</small>`}${ai?`${badge('AI suggestion · Review required','amber')}<small>Suggested Tomato and 2.50 kg. Review both before adding.</small>${button('View captured photo','view-photo','full','type="button"')}`:''}${inputError()}<label class="field">Product<select id="product-select" ${e.editing?'disabled':''}>${M.PRODUCTS.map(p=>`<option value="${p.id}" ${p.id===e.productId?'selected':''}>${p.name}</option>`).join('')}</select></label>${guidance(e,p)}<label class="quantity-label" for="quantity">${p.unit==='kg'?'Weight (kg)':'Quantity (bunches)'}</label><div class="stepper">${button('−','step','', 'type="button" data-delta="-1" aria-label="Decrease quantity"')}<input id="quantity" inputmode="decimal" type="text" value="${esc(e.qty)}" aria-label="${p.unit==='kg'?'Weight (kg)':'Quantity (bunches)'}" autocomplete="off">${button('+','step','','type="button" data-delta="1" aria-label="Increase quantity"')}</div><label class="field">${p.guidance?'Rate':'Final rate'} (₹/${p.unit})<input id="rate" inputmode="decimal" type="text" value="${esc(e.rate)}" autocomplete="off"></label><small>Catalog unit: ${p.unit} · Final rate is yours to choose.</small><p id="pending-total">This item · ${+e.qty>0&&+e.rate>0?M.money(M.total([{qty:e.qty,rate:e.rate}])):'—'}</p><button class="btn primary full" type="submit">${e.editing?'Save changes':'Add to bill'}</button>${button(e.editing?'Cancel changes':'Use AI capture',e.editing?'cancel-editor':'ai-capture','full','type="button"')}</form>`;}
function bill(){if(!items().length)return `${marketBlock()}<section class="panel flow-card"><h2>Your bill is empty</h2><p class="muted">Add a product to start this bill.</p>${link('Add your first product','catalog','primary full')}</section>`;return `${marketBlock()}<section class="panel flow-card"><h2>Items in this bill</h2><small>${count(items().length,'added item')} · Draft</small>${productLines(items(),true)}${link(icon('bill-imgIcon16Plus')+' Add another product','catalog','full')}</section>`;}
function review(){return `${marketBlock()}<section class="panel flow-card"><h2>Review your bill</h2><small>${count(items().length,'added item')} · Draft</small>${items().map(i=>`<div class="review-item"><p>${esc(i.name)}</p><small>${qstr(i)} ${i.unit} × ${M.money(i.rate)}/${i.unit}</small><b>${M.money(M.amount(i)/100)}</b></div>`).join('')}<b class="amount-medium">${M.money(M.total(items()))}</b><small>Added lines only. Pending editor values are excluded.</small>${link('Back to edit','bill','primary full')}</section>`;}
function contact(){return `${marketBlock()}<form id="contact-form" class="panel flow-card"><h2>Review before saving</h2><p class="muted">Check every product, quantity and final rate. Your bill is still a draft.</p>${inputError()}<label class="field">Customer phone (optional)<input id="phone" type="tel" inputmode="tel" autocomplete="off" placeholder="10-digit mobile number" value="${esc(state.draft?.contactInput??state.draft?.phone??'')}"></label><small>Leave blank to save without sending a receipt.</small>${badge('Not saved yet','neutral')}<small>Confirm & save records this bill. Adding an item never saves it.</small>${link('Return to item entry','bill','full')}</form>`;}
function confirm(){return `${marketBlock()}<section class="panel flow-card"><div class="icon-heading">${icon('confirm-imgIconEV2Data20FileText')}<h2>Save this bill?</h2></div><b class="amount-medium">${M.money(M.total(items()))}</b><h3>Products in this bill</h3>${productLines(items())}<p>${count(items().length,'product')} · ${M.market(state.selected).name} · Stall ${state.selectedStall}. ${state.draft?.phone?'Receipt to +91 '+state.draft.phone+'.':'No receipt requested.'} Confirm & Save records the transaction.</p>${link('Back to review','review','full')}</section>`;}
function savingPage(mode){const snapshot=state.saveRequest?.snapshot,ls=snapshot?.items||items();const texts={saving:['Saving your bill…','Keep this screen open. We are checking the save result. Do not start another save.'],failed:['Bill wasn’t saved','Your draft is still here. Retry the same save attempt; no receipt has been sent.'],unknown:['Checking whether your bill saved','Connection was interrupted. Check the existing save result before retrying. Do not create a new bill to repeat this transaction.']};return `${marketBlock(snapshot?.marketId||state.selected,false,M.stallFor(snapshot)||state.selectedStall)}<section class="panel flow-card"><div class="icon-heading">${mode==='saving'?'<span class="spinner"></span>':icon(mode==='failed'?'save-failed':'save-unknown')}<h2>${texts[mode][0]}</h2></div><b class="amount-medium">${M.money(M.total(ls))}</b><h3>Products in this bill</h3>${productLines(ls)}<p>${texts[mode][1]}</p>${mode==='saving'?button('Saving…','noop','full','disabled'):mode==='failed'?button('Retry save','save','primary full')+link('Back to review','review','full'):button('Check save status','check-save','primary full')}</section>`;}
function savedSummary(b){const m=M.market(b.marketId);return `<section class="panel snapshot"><h3>${m.name}</h3><small>Stall ${M.stallFor(b)}</small><b class="metric">${M.money(M.total(b.items))}</b><h3>Products in this bill</h3>${productLines(b.items)}</section>`;}
function saved(id){const b=billById(id);if(!b)return missingBill();return `<section class="success-banner">${icon('saved-imgBillSavedCheck')}<h2>Bill saved successfully</h2></section>${savedSummary(b)}<section class="panel compact"><p>${receiptText[b.receipt]}</p><small>${b.phone?'+91 '+b.phone+' · '+(b.receipt==='sent'?'Delivery confirmed.':'Delivery is not yet confirmed.'):'Saved without sending a receipt.'}</small></section>`;}
function receipt(id){const b=billById(id);if(!b)return missingBill();const rs=b.receipt;const title={ready:'Receipt ready to send',sending:'Sending receipt…',sent:'Receipt sent',failed:'Bill saved · Receipt failed',not_requested:'No receipt requested'}[rs];const copy={ready:`Your bill is saved. Send the receipt to +91 ${b.phone}.`,sending:`Bill saved · Sending to +91 ${b.phone}. Leaving this screen does not undo the bill.`,sent:`Delivered to +91 ${b.phone}. Your saved bill is available in History.`,failed:`Couldn’t deliver to +91 ${b.phone}. Retry delivery; do not save the bill again.`,not_requested:'Your bill is saved. No phone number was provided for a receipt.'}[rs];return `<section class="panel"><div class="icon-heading"><span class="status-well ${rs==='sent'?'success':rs==='failed'?'warning':'blue'}">${rs==='sending'?'<span class="spinner"></span>':icon(rs==='sent'?'receipt-imgReceiptStatusIcon':rs==='failed'?'receipt-failed':'confirm-imgIconEV2Data20FileText')}</span><h2>${title}</h2></div><p>${copy}</p></section><section class="panel snapshot"><small>${M.market(b.marketId).name} · Stall ${M.stallFor(b)}</small><small>${b.id} · ${count(b.items.length,'product')}</small><b class="amount-medium">${M.money(M.total(b.items))}</b><h3>Products in this bill</h3>${productLines(b.items)}</section>${['ready','failed'].includes(rs)?button(rs==='failed'?'Retry receipt':'Send receipt','send-receipt','primary full',`data-id="${b.id}"`):rs==='sending'?button('Check delivery status','check-receipt','primary full',`data-id="${b.id}"`):button('View history','history','primary full',`data-market="${b.marketId}"`)}${rs==='failed'?link('View saved bill','detail/'+b.id,'full'):button('Start next bill','next','full')}`;}
function filteredBills(){return state.bills.filter(b=>(historyMarket==='all'||b.marketId===historyMarket)&&b.id.toLowerCase().includes(historyQuery.toLowerCase()));}
function history(){const bs=state.bills.filter(b=>historyMarket==='all'||b.marketId===historyMarket);return `${marketBlock(historyMarket)}<section class="panel flow-card history-summary"><div class="section-heading"><b>Today · 16 September</b>${icon('history-imgIconEV2Data20FileText')}</div><div class="section-heading"><b class="metric">${M.money(M.total(bs.flatMap(b=>b.items)))}</b><small>${count(bs.length,'saved bill')}</small></div><small>Recorded bill total · ${historyMarket==='all'?'All assigned markets':M.market(historyMarket).name}</small></section><label class="search">${icon('history-imgIcon16Search')}<input id="history-search" type="search" value="${esc(historyQuery)}" placeholder="Search bill ID" aria-label="Search bill ID"></label><section class="panel ledger history-ledger"><h3>Saved bills</h3><div id="history-results">${historyResults()}</div></section><small>All saved bills in this market are shown below.</small>`;}
function historyResults(){const bs=filteredBills();return historyRows(bs,historyMarket==='all')||`<div class="empty-inline"><h3>${historyQuery?'No matching bills':'No saved bills yet'}</h3><p>${historyQuery?'Try another bill ID.':'Your saved transactions will appear here.'}</p></div>`;}
function detail(id){const b=billById(id);if(!b)return missingBill();return `<section class="panel"><h3 class="eyebrow">Saved bill</h3><h2>${b.id}</h2><small>16 Sep 2026 · ${b.time} · ${count(b.items.length,'product')}</small><b class="metric">${M.money(M.total(b.items))}</b><small>${M.market(b.marketId).name} · Stall ${M.stallFor(b)}</small></section><section class="panel snapshot"><h3>Products in this bill</h3>${productLines(b.items)}</section><section class="panel"><h3>Receipt delivery</h3><small>${receiptText[b.receipt]}${b.phone?' to +91 '+b.phone:''}</small>${!['sent','not_requested'].includes(b.receipt)?link('View receipt status','receipt/'+b.id,'full'):''}</section>${button('View history','history','primary full',`data-market="${b.marketId}"`)}${button('Start next bill','next','full')}`;}
function missingBill(){return `<section class="panel"><h2>Bill not found</h2><p>This bill is not available in this browser.</p>${button('View history','history','primary full')}</section>`;}
function capture(stage='capture'){let body='';if(stage==='capture')body=`<h2>Capture product & scale</h2><p>Keep the product and scale digits in view. Take one clear photo.</p><small>Illustrative photo · Check the result before adding</small>${button('Take photo','take-photo','primary full')}${button('Select image','select-image','full')}`;if(stage==='image')body=`<h2>Check your image</h2><p>Make sure the product and scale reading are clear before analysis.</p><img class="capture-image" src="${aiUrl||'assets/sample-scale.png'}" alt="Selected product and weighing scale"><small>${aiSample?'Illustrative photo · Check the result before adding':'Selected photo · Demo analysis returns sample values'}</small>${button('Analyze image','analyze','primary full')}${button('Choose another image','select-image','full')}`;if(stage==='analyzing')body=`<div class="icon-heading"><span class="spinner"></span><h2>Analyzing image…</h2></div><p>Checking the product and scale reading.</p>${button('Cancel analysis','cancel-analysis','full')}`;if(stage==='failed')body=`<h2>Couldn’t read this image</h2><p>Your bill is unchanged. Try a clearer photo or enter the product manually.</p>${button('Try another image','select-image','primary full')}`;return `${marketBlock()}<section class="panel flow-card">${body}${stage!=='analyzing'?button('Enter manually','manual','full'):''}</section><input id="camera-input" type="file" accept="image/*" capture="environment" hidden><input id="image-input" type="file" accept="image/*" hidden>`;}
function getView(){const [r,id]=route();let title='Farmer Billing',body='',footer='',back='home',menu=false;const requireMarket=['catalog','editor','ai-capture','ai-image','ai-analyzing','ai-failed','ai-review','bill','review','contact','confirm'];if(requireMarket.includes(r)&&!state.selected)return {title:'Select market',body:markets(),back:'home'};if(['review','contact','confirm'].includes(r)&&!items().length)return {title:'Current bill',body:bill(),back:'home'};
 switch(r){case'home':body=home();menu=true;break;case'markets':title='Select market';body=markets();back=marketReturn;break;case'stalls':title='Select stall';body=stalls(id);back='markets';if(M.market(id)&&!M.market(id).closed)footer=`<footer class="app-footer">${button('Confirm stall','confirm-stall','primary full',state.selection?.marketId===id&&M.market(id).stalls.includes(state.selection?.stallId)?'':'disabled')}</footer>`;break;case'catalog':title=items().length?'Add another product':'New bill';body=catalog();back=items().length?'bill':'home';footer=totalsFooter('View bill','view-bill');break;case'editor':case'ai-review':title=r==='ai-review'?'Review AI result':state.editor?.editing?'Edit product':M.product(state.editor?.productId)?.guidance?'Final rate':'Add product';body=editor(r==='ai-review');back=items().length?'bill':'catalog';footer=totalsFooter('View bill','view-bill');break;case'bill':title='Current bill';body=bill();menu=true;footer=totalsFooter('Continue to checkout','review',true);break;case'review':title='Review bill';body=review();back='bill';footer=totalsFooter('Continue to contact','contact',true);break;case'contact':title='Receipt contact';body=contact();back='review';footer=totalsFooter('Review & confirm','validate-contact',true);break;case'confirm':title='Confirm & save';body=confirm();back='contact';footer=totalsFooter('Confirm & save','save',true);break;case'saving':title='Saving bill';body=savingPage('saving');back='saving';break;case'save-failed':title='Save status';body=savingPage('failed');back='review';break;case'save-unknown':title='Save status';body=savingPage('unknown');back='save-unknown';break;case'saved':title='Bill saved';body=saved(id||state.lastSaved);menu=true;footer=`<footer class="app-footer">${button('Start next bill','next','primary full')}${link('View receipt status','receipt/'+(id||state.lastSaved),'full')}</footer>`;break;case'receipt':title='Receipt';body=receipt(id||state.lastSaved);back='detail/'+(id||state.lastSaved);break;case'history':title='Bill history';body=history();back='home';break;case'detail':title='Bill details';body=detail(id);back='history';break;case'ai-capture':case'ai-image':case'ai-analyzing':case'ai-failed':title='AI capture';body=capture(r.replace('ai-',''));back='catalog';footer=totalsFooter('View bill','view-bill');break;default:body=home();menu=true;}
 return {title,body,footer,back,menu};}
function render(){if(M.locked(state)&&!['saving','save-unknown'].includes(route()[0])){location.hash='save-unknown';return;}const v=getView();app.innerHTML=`<div class="review-tools"><b>Farmer Billing · Mobile</b><div>${button('Review guide','guide','tool-btn')}${button('Demo controls','demo','tool-btn')}</div></div><div class="phone"><header class="app-header"><div class="header-left"><button class="nav-icon" aria-label="${v.menu?'Open menu':'Go back'}" data-action="${v.menu?'menu':'go'}" data-route="${v.back}">${icon(v.menu?'home-imgMenu':'catalog-imgIconEV2Fixed20ArrowLeft')}</button><h1>${v.title}</h1></div><button class="avatar" data-action="account" aria-label="Ramesh profile">RP</button></header><main class="screen ${route()[0]==='home'?'billing-home':''}">${storageFailed?'<div class="form-error">Progress cannot be saved on this browser.</div>':''}${v.body}</main>${v.footer||''}</div><p class="prototype-caption">Final mobile design · Sample data · Progress saved in this browser</p>`;if(route()[0]==='receipt'&&billById(route()[1]||state.lastSaved)?.receipt==='sending')scheduleReceipt(route()[1]||state.lastSaved);}
function modal(title,body,kind=''){dialog.className=kind;dialog.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;dialog.showModal();if(kind==='sheet'){const p=document.querySelector('.phone').getBoundingClientRect();dialog.style.width=Math.min(p.width,window.innerWidth)+'px';dialog.style.left=p.left+'px';dialog.style.top=Math.max(8,Math.min(p.bottom,window.innerHeight)-dialog.getBoundingClientRect().height)+'px';}else if(kind==='item-options'){const anchor=document.querySelector('[data-action="item-menu"][data-id="'+menuLine+'"]');const p=anchor?.getBoundingClientRect();dialog.style.width='180px';dialog.style.left=(p?Math.max(8,p.right-180):window.innerWidth/2-90)+'px';dialog.style.top=(p?Math.min(p.bottom,window.innerHeight-dialog.getBoundingClientRect().height-16):100)+'px';}else{dialog.style.width='';dialog.style.left='';dialog.style.top='';}}
function removeSheet(id){const i=items().find(i=>i.id===id);if(!i)return;dialog.close();const remain=items().filter(x=>x.id!==id);modal('Remove this item?',`<div class="remove-identity"><span>${esc(i.name)} · ${qstr(i)} ${i.unit==='bunch'?'bunches':i.unit}</span><b class="amount-medium">${M.money(M.amount(i)/100)}</b></div><p class="muted">This item will be removed. Your bill will have ${count(remain.length)}, totaling ${M.money(M.total(remain))}.</p><div class="two-actions">${button('Keep item','close','full')}${button('Remove item','remove-confirm','danger primary full',`data-id="${id}"`)}</div>`,'sheet');dialog.querySelector('.modal-head').insertAdjacentHTML('afterbegin',`<span class="status-well red">${icon('remove-imgWarningRemoveItem')}</span>`);const bounds=document.querySelector('.phone').getBoundingClientRect();dialog.style.top=Math.max(8,Math.min(bounds.bottom,window.innerHeight)-dialog.getBoundingClientRect().height)+'px';}
function chooseMarket(id){
 if(marketMode==='history'){historyMarket=id;go('history');return;}
 const m=M.market(id);if(!m||m.closed)throw Error('This market is not open today.');
 state.selection={marketId:id,stallId:state.selected===id?state.selectedStall:null,returnTo:marketReturn};
 persist();go('stalls/'+id);
}
function stalls(id){
 const m=M.market(id);if(!m||m.closed)return `<section class="panel"><h2>Market unavailable</h2><p>Choose an open assigned market to continue.</p>${link('Select market','markets','primary full')}</section>`;
 const selection=state.selection?.marketId===id?state.selection:null;
 return `<section class="market-block"><span class="icon-well">${icon('catalog-imgMarketStore')}</span><span class="market-info"><small>Selected market</small><b>${m.name}</b></span>${link('Change','markets','small-btn')}</section><section class="panel flow-card"><h2>Select your stall</h2><p class="muted">Choose the stall you are billing from at ${m.short}.</p><fieldset class="stall-options"><legend>Assigned stalls</legend>${m.stalls.map(stall=>`<label class="stall-option ${selection?.stallId===stall?'selected':''}"><span><b>Stall ${stall}</b><small>${state.selected===id&&state.selectedStall===stall?'Current stall':'Assigned to you'}</small></span><input type="radio" name="stall" value="${stall}" data-market="${id}" ${selection?.stallId===stall?'checked':''} aria-label="Stall ${stall}"></label>`).join('')}</fieldset><small>New bills will be recorded against the selected market and stall.</small></section>${link('Cancel selection',selection?.returnTo||marketReturn,'full')}`;
}
function confirmStall(discard=false){
 const selection=state.selection;if(!selection)throw Error('Select your stall to continue.');
 const {marketId,stallId,returnTo}=selection,m=M.market(marketId);
 if(!m?.stalls.includes(stallId))throw Error('Select your stall to continue.');
 const changed=state.selected!==marketId||state.selectedStall!==stallId;
 if(changed&&(items().length||state.editor)&&!discard){modal('Change market or stall and discard this draft?',`${badge('Unsaved bill','amber')}<p>From: ${M.market(state.selected).name} · Stall ${state.selectedStall}<br>To: ${m.name} · Stall ${stallId}</p><p class="muted">Discard ${count(items().length,'added item')} (${M.money(M.total(items()))}) and any pending item? Saved bills stay unchanged.</p>${button('Keep current bill','cancel-context','full')}${button('Discard draft & change','discard-context','primary danger full')}`);return;}
 M.selectStall(state,marketId,stallId,discard);persist();go(returnTo==='home'?'home':changed?'catalog':returnTo||'home');
}
function performSave(){const req=M.beginSave(state);if(req.status==='saved'){go('saved/'+state.lastSaved);return;}if(req.status==='unknown'){go('save-unknown');return;}persist();go('saving');const outcome=saveMode;saveMode='success';setTimeout(()=>{if(state.saveRequest?.id!==req.id||state.saveRequest.status!=='pending')return;const b=M.saveOutcome(state,outcome);persist();go(b?'saved/'+b.id:outcome==='failed'?'save-failed':'save-unknown');},1100);}
const receiptTimers=new Map();function scheduleReceipt(id){if(receiptTimers.has(id))return;const outcome=receiptMode;receiptMode='success';receiptTimers.set(id,setTimeout(()=>{M.receiptOutcome(state,id,outcome);persist();receiptTimers.delete(id);if(route()[0]==='receipt')render();},1400));}
function updatePending(){const e=state.editor;if(!e)return;const n=document.querySelector('#pending-total');if(n)n.textContent='This item · '+(+e.qty>0&&+e.rate>0?M.money(M.total([{qty:e.qty,rate:e.rate}])):'—');persist();}
function navigateHistory(mid){historyMarket=mid||state.selected||'all';historyQuery='';go('history');}
function next(){if(!state.selected){marketReturn='home';marketMode='billing';go('markets');return;}if(items().length){modal('Your current bill is still a draft',`<p>Resume this bill to keep adding products.</p>${link('Resume current bill','bill','primary full')}${button('Cancel','close','full')}`);return;}M.nextBill(state);persist();go('catalog');}
function useScenario(which){for(const t of receiptTimers.values())clearTimeout(t);receiptTimers.clear();state=which==='fresh'?M.seed():M.draftScenario();if(which==='empty'){M.selectMarket(state,'vidya');state.draft=M.emptyDraft('vidya');}if(['saved','receipt-failed'].includes(which)){const b=M.finishSave(state,M.beginSave(state).id);if(which==='receipt-failed')b.receipt='failed';}historyMarket=state.selected||'all';historyQuery='';catalogQuery='';error='';saveMode='success';receiptMode='success';persist();go(which==='saved'?'saved/'+state.lastSaved:which==='receipt-failed'?'receipt/'+state.lastSaved:which==='draft'?'bill':'home');}
function demo(){modal('Demo controls',`<p>These controls sit outside the approved mobile screens. They change only the sample in this browser.</p><label class="field">Load a sample<select id="scenario"><option value="fresh">Original home · 3 saved bills</option><option value="empty">Selected market · Empty draft</option><option value="draft">Ready for checkout · ₹93 bill</option><option value="saved">Saved ₹93 bill</option><option value="receipt-failed">Saved bill · Receipt failed</option></select></label>${button('Load sample','load-scenario','full')}<hr><label class="field">Next save result<select id="save-mode">${['success','failed','unknown'].map(x=>`<option ${saveMode===x?'selected':''} value="${x}">${x}</option>`).join('')}</select></label><label class="field">Next receipt delivery<select id="receipt-mode"><option value="success" ${receiptMode==='success'?'selected':''}>Sent</option><option value="failed" ${receiptMode==='failed'?'selected':''}>Failed</option></select></label><label class="field">Market guidance (Coriander)<select id="guidance-mode">${['available','loading','unavailable','failed','stale','late'].map(x=>`<option value="${x}" ${guidanceMode===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">AI sample result<select id="ai-mode"><option value="success">Review required</option><option value="failed">Analysis failed</option></select></label>${button('Apply demo settings','demo-apply','primary full')}${button('Use sample scale photo','sample-photo','full')}<small>AI, market guidance, saving and receipt delivery are simulated. No messages are sent. Demo date: 16 September 2026.</small>`);}
function guide(){modal('Review the mobile prototype',`<p>Use the approved 375 × 812 mobile screens with editable sample values. Progress stays in this browser.</p><ol><li>Select Vidya Vikas, choose Stall A-12, confirm the stall, then start a bill and choose Tomato. Enter 2.50 kg at ₹25 and add it.</li><li>Add Coriander Bunch, enter 2 and explicitly apply the ₹12 suggestion.</li><li>Open an item’s three-dot menu. Edit Tomato to 3 kg, remove Coriander, then add 1 kg Potato at ₹18. The bill totals ₹93.</li><li>Review the products, enter an optional receipt phone, then confirm and save.</li><li>Open receipt status and send the simulated receipt. Find the saved bill in History, then start another bill.</li><li>Use Demo controls to try save failures, unknown outcomes, receipt retries, and the AI sample-photo path.</li></ol><p>New inputs work beyond this walkthrough. Saved bills retain their own product snapshot. Camera/upload can select a local photo, but AI analysis returns clearly labelled sample values. Prices and receipt delivery are demonstrations.</p>${button('Start reviewing','close','primary full')}`);}
async function filePicked(file){if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file.');return;}if(file.size>15*1024*1024){toast('Choose an image smaller than 15 MB.');return;}if(aiUrl?.startsWith('blob:'))URL.revokeObjectURL(aiUrl);aiUrl=URL.createObjectURL(file);aiSample=false;go('ai-image');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;try{switch(a){case'noop':break;case'go':go(b.dataset.route);break;case'close':dialog.close();break;case'guide':guide();break;case'demo':demo();break;case'account':modal('Ramesh Patil','<p>Farmer · Assigned markets in Nashik</p><small>Sample profile for this mobile prototype.</small>'+button('Close','close','full'));break;case'menu':modal('Farmer Billing',link('Home','home','full')+link('Current bill','bill','full')+button('Bill history','history','full')+button('Close','close','full'));break;case'market-info':toast('This bill belongs to '+M.market(state.saveRequest?.snapshot?.marketId||state.selected).name+'.');break;case'open-markets':case'history-market':marketReturn=route().join('/');marketMode=route()[0]==='history'?'history':'billing';go('markets');break;case'select-market':chooseMarket(id);break;case'confirm-stall':confirmStall();break;case'discard-context':confirmStall(true);break;case'cancel-context':{const destination=state.selection?.returnTo||'bill';state.selection=null;persist();go(destination);break;}case'start':if(!state.draft)M.nextBill(state);persist();go(items().length?'bill':'catalog');break;case'next':next();break;case'select-product':startEditor(id,items().find(i=>i.productId===id)?.id);break;case'step':{const ed=state.editor,p=M.product(ed.productId);ed.qty=String(Math.max(p.step,Math.round(((+ed.qty||0)+Number(b.dataset.delta)*p.step)*1000)/1000));document.querySelector('#quantity').value=ed.qty;updatePending();break;}case'apply-guidance':state.editor.rate=String(M.product(state.editor.productId).guidance.rate);state.editor.guidance='applied';persist();render();break;case'load-guidance':state.editor.guidance='available';persist();render();break;case'cancel-editor':state.editor=null;persist();go(items().length?'bill':'catalog');break;case'view-bill':go('bill');break;case'item-menu':menuLine=id;modal(items().find(i=>i.id===id).name,button('Edit item','edit-line','full',`data-id="${id}"`)+button('Remove item','remove-line','full danger',`data-id="${id}"`),'item-options');break;case'edit-line':{const i=items().find(i=>i.id===id);dialog.close();startEditor(i.productId,id);break;}case'remove-line':removeSheet(id);break;case'remove-confirm':M.removeLine(state,id);persist();dialog.close();render();break;case'review':go('review');break;case'contact':go('contact');break;case'validate-contact':document.querySelector('#contact-form').requestSubmit();break;case'save':performSave();break;case'check-save':{const result=M.finishSave(state,state.saveRequest.id);persist();go('saved/'+result.id);break;}case'send-receipt':M.sendReceipt(state,id);persist();render();scheduleReceipt(id);break;case'check-receipt':scheduleReceipt(id);toast('Checking receipt delivery…');break;case'history':navigateHistory(b.dataset.market);break;case'detail':go('detail/'+id);break;case'ai-capture':go('ai-capture');break;case'take-photo':document.querySelector('#camera-input').click();break;case'select-image':document.querySelector('#image-input').click();break;case'sample-photo':if(!state.selected){M.selectMarket(state,'vidya');persist();}aiUrl=null;aiSample=true;go('ai-image');break;case'view-photo':modal('Captured photo',`<img class="capture-image" src="${aiUrl||'assets/sample-scale.png'}" alt="Product and weighing scale">`);break;case'analyze':{const token=++aiToken;go('ai-analyzing');setTimeout(()=>{if(token!==aiToken||route()[0]!=='ai-analyzing')return;if(aiMode==='failed'){go('ai-failed');return;}startEditor('tomato',null,true);},1200);break;}case'cancel-analysis':aiToken++;go('ai-image');break;case'manual':aiToken++;go('catalog');break;case'load-scenario':modal('Replace demo progress?',`<p>This resets only the sample bills and draft in this browser.</p>${button('Keep my progress','close','full')}${button('Load selected sample','confirm-scenario','primary full',`data-scenario="${document.querySelector('#scenario').value}"`)}`);break;case'confirm-scenario':useScenario(b.dataset.scenario);break;case'demo-apply':saveMode=document.querySelector('#save-mode').value;receiptMode=document.querySelector('#receipt-mode').value;guidanceMode=document.querySelector('#guidance-mode').value;aiMode=document.querySelector('#ai-mode').value;if(state.editor)state.editor.guidance=guidanceMode;persist();dialog.close();render();toast('Demo settings applied.');break;}}catch(err){error=err.message;if(dialog.open)toast(error);else render();}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='catalog-search'){catalogQuery=t.value;document.querySelector('#catalog-results').innerHTML=catalogResults();}if(t.id==='history-search'){historyQuery=t.value;document.querySelector('#history-results').innerHTML=historyResults();}if(t.id==='quantity'||t.id==='rate'){state.editor[t.id==='quantity'?'qty':'rate']=t.value;if(t.id==='rate'&&state.editor.guidance==='applied'){state.editor.guidance='available';const panel=document.querySelector('.guidance');if(panel)panel.outerHTML=guidance(state.editor,M.product(state.editor.productId));}updatePending();}if(t.id==='phone'){state.draft.contactInput=t.value;persist();}});
document.addEventListener('change',e=>{const t=e.target;if(t.name==='stall'){const id=t.dataset.market;state.selection={marketId:id,stallId:t.value,returnTo:state.selection?.returnTo||marketReturn};persist();render();}if(t.id==='product-select'){state.editor.productId=t.value;state.editor.rate=String(M.product(t.value).rate);state.editor.qty='';state.editor.guidance=guidanceMode;persist();render();}if(['camera-input','image-input'].includes(t.id))filePicked(t.files[0]);});
document.addEventListener('submit',e=>{if(!['editor-form','contact-form'].includes(e.target.id))return;e.preventDefault();try{if(e.target.id==='editor-form'){M.commitLine(state,state.editor);persist();go('bill');}else{M.setPhone(state,document.querySelector('#phone').value);delete state.draft.contactInput;persist();go('confirm');}}catch(err){error=err.message;render();}});
dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
window.addEventListener('hashchange',()=>{error='';render();});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const next=JSON.parse(e.newValue);if(next.schema===1){state=M.migrate(next);render();toast('Demo progress updated in another tab.');}}catch{}}});
try{void Promise.resolve(document.modelContext?.registerTool({name:'read_farmer_billing_demo',description:'Read sample Farmer Billing mobile state: selected market, committed draft total, saved bill totals and receipt states. Phone numbers are omitted.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async args=>{if(Object.keys(args||{}).length)throw Error('This tool takes no arguments.');return {content:[{type:'text',text:JSON.stringify({sampleData:true,market:state.selected,stall:state.selectedStall,draft:{items:items().length,total:M.total(items())},saveStatus:state.saveRequest?.status||null,bills:state.bills.map(b=>({id:b.id,market:b.marketId,stall:M.stallFor(b),total:M.total(b.items),products:b.items.length,receipt:b.receipt}))})}]};}})).catch(()=>{});}catch{}
persist();render();
